<?php
defined('SECURE_ENTRY') or define('SECURE_ENTRY', true);

// Example hex-encoded content from the first encoder.html (replace with your actual encoded content)
$encodedContent = "";

// Decode the hex content in the backend
$decodedContent = @hex2bin($encodedContent);

// Fallback if decoding fails or returns invalid data
if ($decodedContent === false) {
    $decodedContent = "<p>Error decoding content.</p>";
} else {
    $decodedContent = mb_convert_encoding($decodedContent, 'UTF-8', 'UTF-8');
    if (!mb_check_encoding($decodedContent, 'UTF-8')) {
        $decodedContent = "<p>Decoded content is not valid UTF-8.</p>";
    }
}
?>